import React, { useState, useEffect } from 'react';
import { getApplications, getStats } from '../services/api';
import Navbar from '../components/Navbar';
import ApplicationForm from '../components/ApplicationForm';
import ApplicationTable from '../components/ApplicationTable';
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const COLORS = ['#3b82f6', '#f59e0b', '#8b5cf6', '#10b981', '#ef4444'];

export default function Dashboard() {
  const [applications, setApplications] = useState([]);
  const [stats, setStats] = useState([]);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    getApplications().then(res => setApplications(res.data));
    getStats().then(res => {
      setStats(res.data.stats);
      setTotal(res.data.total);
    });
  }, []);

  useEffect(() => {
    getStats().then(res => {
      setStats(res.data.stats);
      setTotal(res.data.total);
    });
  }, [applications]);

  const getCount = (status) => {
    const found = stats.find(s => s.status === status);
    return found ? found.count : 0;
  };

  const statCards = [
    { label: 'Total', value: total, color: '#4f46e5' },
    { label: 'Interviews', value: getCount('Interview'), color: '#8b5cf6' },
    { label: 'Offers', value: getCount('Offer'), color: '#10b981' },
    { label: 'Rejected', value: getCount('Rejected'), color: '#ef4444' },
  ];

  return (
    <div style={styles.page}>
      <Navbar />
      <div style={styles.container}>

        <div style={styles.statsRow}>
          {statCards.map(function(stat) {
            return (
              <div key={stat.label} style={{
                flex: '1', minWidth: '140px', background: '#fff',
                borderRadius: '12px', padding: '1.25rem',
                boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
                borderTop: '4px solid ' + stat.color
              }}>
                <p style={styles.statLabel}>{stat.label}</p>
                <p style={{ margin: 0, fontSize: '2rem', fontWeight: 'bold', color: stat.color }}>{stat.value}</p>
              </div>
            );
          })}
        </div>

        {stats.length > 0 && (
          <div style={styles.chartCard}>
            <h3 style={styles.sectionTitle}>Applications by Status</h3>
            <ResponsiveContainer width="100%" height={250}>
              <PieChart>
                <Pie data={stats} dataKey="count" nameKey="status" cx="50%" cy="50%" outerRadius={80} label>
                  {stats.map(function(entry, i) {
                    return <Cell key={i} fill={COLORS[i % COLORS.length]} />;
                  })}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        )}

        <ApplicationForm onAdd={function(app) { setApplications(function(prev) { return [app, ...prev]; }); }} />

        <h3 style={styles.sectionTitle}>Your Applications</h3>
        <ApplicationTable applications={applications} setApplications={setApplications} />

      </div>
    </div>
  );
}

const styles = {
  page: { minHeight: '100vh', background: '#f0f2f5' },
  container: { maxWidth: '1100px', margin: '0 auto', padding: '2rem 1rem' },
  statsRow: { display: 'flex', gap: '1rem', marginBottom: '1.5rem', flexWrap: 'wrap' },
  statLabel: { margin: '0 0 0.5rem', color: '#666', fontSize: '0.9rem' },
  chartCard: { background: '#fff', borderRadius: '12px', padding: '1.5rem', boxShadow: '0 2px 8px rgba(0,0,0,0.08)', marginBottom: '1.5rem' },
  sectionTitle: { marginTop: 0, marginBottom: '1rem', color: '#1a1a2e' }
};
